#include <string>
#include <vector>
#include <map>
#include <chrono>
#include <mutex>
#include <functional>
#include <algorithm>
#include <cstring>

namespace iot_auth {

enum class CircuitState { CLOSED, OPEN, HALF_OPEN };

struct CircuitBreaker {
    CircuitState state = CircuitState::CLOSED;
    int failure_count = 0;
    int success_count = 0;
    static constexpr int FAILURE_THRESHOLD = 5;
    static constexpr int SUCCESS_THRESHOLD = 3;
    std::chrono::steady_clock::time_point last_failure;
    std::chrono::seconds cooldown{30};
    std::mutex mtx;

    bool allow_request() {
        std::lock_guard<std::mutex> lock(mtx);
        if (state == CircuitState::CLOSED) return true;
        if (state == CircuitState::OPEN) {
            auto now = std::chrono::steady_clock::now();
            if (now - last_failure > cooldown) {
                state = CircuitState::HALF_OPEN;
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows probe requests
    }

    void record_success() {
        std::lock_guard<std::mutex> lock(mtx);
        if (state == CircuitState::HALF_OPEN) {
            success_count++;
            if (success_count >= SUCCESS_THRESHOLD) {
                state = CircuitState::CLOSED;
                failure_count = 0;
                success_count = 0;
            }
        }
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mtx);
        failure_count++;
        last_failure = std::chrono::steady_clock::now();
        if (failure_count >= FAILURE_THRESHOLD) {
            state = CircuitState::OPEN;
            success_count = 0;
        }
    }
};

struct OAuthConfig {
    std::string client_id;
    std::string auth_endpoint;
    std::vector<std::string> allowed_redirect_uris;
    std::string device_id;
};

class RedirectValidator {
private:
    OAuthConfig config_;
    CircuitBreaker breaker_;

    // Normalize URI by resolving percent-encoding
    std::string normalize_uri(const std::string& uri) const {
        std::string result;
        result.reserve(uri.size());
        for (size_t i = 0; i < uri.size(); i++) {
            if (uri[i] == '%' && i + 2 < uri.size()) {
                char high = uri[i+1];
                char low = uri[i+2];
                auto hex_val = [](char c) -> int {
                    if (c >= '0' && c <= '9') return c - '0';
                    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
                    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
                    return -1;
                };
                int h = hex_val(high), l = hex_val(low);
                if (h >= 0 && l >= 0) {
                    result += static_cast<char>((h << 4) | l);
                    i += 2;
                } else {
                    result += uri[i];
                }
            } else {
                result += uri[i];
            }
        }
        return result;
    }

    // Exact match validation against whitelist
    bool uri_matches(const std::string& normalized_uri) const {
        // Perform exact match against registered redirect URIs
        for (const auto& allowed : config_.allowed_redirect_uris) {
            std::string normalized_allowed = normalize_uri(allowed);
            if (normalized_uri == normalized_allowed) return true;
        }
        return false;
    }

public:
    RedirectValidator(const OAuthConfig& config) : config_(config) {}

    // Validate redirect URI with circuit breaker protection
    bool validate_redirect(const std::string& redirect_uri) {
        if (!breaker_.allow_request()) {
            return false; // Circuit open, reject all
        }

        if (redirect_uri.empty()) {
            breaker_.record_failure();
            return false;
        }

        std::string normalized = normalize_uri(redirect_uri);

        // Security check: reject URIs with embedded credentials
        if (normalized.find('@') != std::string::npos) {
            breaker_.record_failure();
            return false;
        }

        // Security check: reject URIs with path traversal
        if (normalized.find("..") != std::string::npos) {
            breaker_.record_failure();
            return false;
        }

        // Security check: only allow https scheme
        if (normalized.substr(0, 8) != "https://") {
            breaker_.record_failure();
            return false;
        }

        // Exact match validation - no subdomain or prefix matching
        if (uri_matches(normalized)) {
            breaker_.record_success();
            return true;
        }

        breaker_.record_failure();
        return false;
    }

    CircuitState get_circuit_state() const {
        return breaker_.state;
    }
};

// Device firmware OAuth handler
class DeviceOAuthHandler {
private:
    RedirectValidator validator_;
    std::string pending_state_;

    // Percent-encode a value so it is safe to embed as a query parameter value.
    // Prevents parameter injection / response-splitting via attacker-controlled input.
    static std::string url_encode(const std::string& value) {
        static const char hex[] = "0123456789ABCDEF";
        std::string out;
        out.reserve(value.size() * 3);
        for (unsigned char c : value) {
            bool unreserved = (c >= 'A' && c <= 'Z') ||
                              (c >= 'a' && c <= 'z') ||
                              (c >= '0' && c <= '9') ||
                              c == '-' || c == '_' || c == '.' || c == '~';
            if (unreserved) {
                out += static_cast<char>(c);
            } else {
                out += '%';
                out += hex[(c >> 4) & 0xF];
                out += hex[c & 0xF];
            }
        }
        return out;
    }

public:
    DeviceOAuthHandler(const OAuthConfig& config) : validator_(config) {}

    struct AuthResponse {
        bool success;
        std::string redirect_location;
        std::string error;
    };

    AuthResponse initiate_auth(const std::string& redirect_uri,
                               const std::string& state) {
        AuthResponse resp{};

        if (redirect_uri.empty()) {
            resp.error = "missing_redirect_uri";
            return resp;
        }

        if (!validator_.validate_redirect(redirect_uri)) {
            resp.error = "invalid_redirect_uri";
            return resp;
        }

        pending_state_ = state;
        resp.success = true;
        // Percent-encode the state value to prevent query-parameter injection
        // and control-character injection into the redirect location.
        resp.redirect_location = redirect_uri + "?code=AUTH_CODE&state=" + url_encode(state);
        return resp;
    }
};

} // namespace iot_auth
